        {activeTab === 'forecast' && (
          <div className="space-y-6 animate-in fade-in duration-500">
            <header className="px-1">
               <h1 className="text-xl font-black text-slate-800 uppercase">Previsões do Mês</h1>
               <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Planejamento e Hipóteses</p>
            </header>

            <div className="bg-amber-50 p-8 rounded-[40px] border-2 border-amber-100 shadow-sm text-center">
               <p className="text-[10px] font-bold text-amber-600 uppercase tracking-widest mb-2">Saldo Final Estimado (Com Previsões)</p>
               <h2 className={`text-4xl font-black tracking-tight ${stats.forecastTotal >= 0 ? 'text-amber-700' : 'text-rose-500'}`}>
                 {formatCurrency(stats.forecastTotal)}
               </h2>
               <p className="text-[9px] font-bold text-amber-500/60 uppercase mt-4">
                 Soma do Saldo Projetado + Previsões de Lançamento
               </p>
            </div>

            <div className="space-y-3">
               <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Lançamentos de Previsão</h3>
               {transactions.filter(t => isTransactionInMonth(t, viewingYear, viewingMonth) && t.type.startsWith('PROSPECT')).length === 0 ? (
                 <div className="bg-white p-10 rounded-3xl border-2 border-dashed border-slate-100 text-center">
                    <p className="text-slate-300 text-[10px] font-bold uppercase">Nenhuma previsão para este mês</p>
                 </div>
               ) : (
                 transactions.filter(t => isTransactionInMonth(t, viewingYear, viewingMonth) && t.type.startsWith('PROSPECT')).map(t => (
                   <div key={t.id} className="bg-white p-5 rounded-2xl border-2 border-amber-100 flex items-center justify-between shadow-sm">
                     <div className="flex items-center gap-4">
                       <div className="w-10 h-10 bg-amber-50 text-amber-500 rounded-xl flex items-center justify-center"><i className="fa-solid fa-wand-magic-sparkles"></i></div>
                       <div>
                         <p className="font-bold text-sm text-slate-700">{t.description}</p>
                         <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{t.category} • {formatDate(t.date)}</p>
                       </div>
                     </div>
                     <div className="text-right">
                       <p className="text-sm font-black text-amber-600">-{formatCurrency(t.amount)}</p>
                       <button onClick={() => handleDelete(t.id)} className="text-[9px] font-bold text-rose-400 uppercase mt-1">Excluir</button>
                     </div>
                   </div>
                 ))
               )}
            </div>
          </div>
        )}

        {activeTab === 'extract' && (
          <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex justify-between items-center px-1">
              <h2 className="text-lg font-black text-slate-800 uppercase tracking-tight">Movimentação</h2>
              <div className="flex bg-slate-100 p-1 rounded-xl border border-slate-200">
                <button 
                  onClick={() => setExtractMode('realized')}
                  className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${extractMode === 'realized' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-400'}`}
                >
                  Efetuado
                </button>
                <button 
                  onClick={() => setExtractMode('future')}
                  className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${extractMode === 'future' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-400'}`}
                >
                  Futuros/Previstos
                </button>
              </div>
            </div>

            <div className="space-y-8">
              {groupedExtract.length === 0 ? (
                <div className="text-center py-20 bg-white rounded-3xl border-2 border-dashed border-slate-100">
                   <p className="text-slate-300 text-[10px] font-bold uppercase">Nenhum registro encontrado</p>
                </div>
              ) : (
                groupedExtract.map(group => (
                  <div key={group.date} className="space-y-3">
                    <div className="flex justify-between items-center px-1">
                       <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">{formatDate(group.date)}</h3>
                       <span className={`text-[10px] font-black px-2 py-0.5 rounded-md ${group.dayBalance >= 0 ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                         Dia: {group.dayBalance >= 0 ? '+' : ''}{formatCurrency(group.dayBalance)}
                       </span>
                    </div>
                    <div className="space-y-2">
                      {group.items.map(t => (
                        <div key={t.id + (t.isFixed ? '-fixed' : '')} className="flex flex-col">
                          <div 
                            onClick={() => setFocusedTransactionId(focusedTransactionId === t.id ? null : t.id)}
                            className={`bg-white p-5 rounded-2xl border-2 flex items-center justify-between shadow-sm group transition-all cursor-pointer ${focusedTransactionId === t.id ? 'border-blue-400' : t.type.startsWith('PROSPECT') ? 'border-amber-100 hover:border-amber-200' : 'border-slate-50 hover:border-blue-100'}`}
                          >
                            <div className="flex items-center gap-4">
                              <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${t.type.includes('INCOME') ? 'bg-emerald-50 text-emerald-500' : t.type.startsWith('PROSPECT') ? 'bg-amber-50 text-amber-500' : 'bg-rose-50 text-rose-500'}`}>
                                <i className={`fa-solid ${t.type.includes('INCOME') ? 'fa-arrow-trend-up' : t.type.startsWith('PROSPECT') ? 'fa-wand-magic-sparkles' : 'fa-arrow-trend-down'}`}></i>
                              </div>
                              <div>
                                <p className="text-sm font-bold text-slate-700">
                                  {t.description} 
                                  {t.isFixed && <span className="text-[7px] bg-blue-100 text-blue-500 px-1.5 py-0.5 rounded ml-1 uppercase">FIXO</span>}
                                  {t.type.startsWith('PROSPECT') && <span className="text-[7px] bg-amber-100 text-amber-600 px-1.5 py-0.5 rounded ml-1 uppercase">PREVISTO</span>}
                                </p>
                                <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{t.isFixed ? 'Custo Fixo' : t.category}</p>
                              </div>
                            </div>
                            <div className="flex items-center gap-4">
                              <p className={`text-sm font-black ${t.type.includes('INCOME') ? 'text-emerald-500' : t.type.startsWith('PROSPECT') ? 'text-amber-500' : 'text-slate-700'}`}>
                                {t.type.includes('INCOME') ? '+' : '-'}{formatCurrency(t.amount)}
                              </p>
                            </div>
                          </div>
                          {focusedTransactionId === t.id && (
                            <div className="flex gap-2 p-2 bg-slate-100/50 rounded-b-2xl mx-4 animate-in slide-in-from-top-2 duration-200">
                              <button onClick={(e) => { e.stopPropagation(); handleEdit(t); }} className="flex-1 bg-white text-[9px] font-bold text-slate-600 py-2 rounded-lg border border-slate-200 shadow-sm">EDITAR</button>
                              <button onClick={(e) => { e.stopPropagation(); handleDelete(t.id); }} className="flex-1 bg-white text-[9px] font-bold text-rose-500 py-2 rounded-lg border border-slate-200 shadow-sm">EXCLUIR</button>
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        )}

        {activeTab === 'calendar' && (
          <div className="space-y-6 animate-in fade-in duration-500">
             <FinancialCalendar transactions={transactions} onDateClick={handleDayClick} viewMonth={viewingMonth} viewYear={viewingYear} />
             {selectedDay && (
               <div className="bg-white p-6 rounded-3xl border-2 border-slate-100 shadow-xl animate-in slide-in-from-bottom-4 duration-300">
                  <div className="flex justify-between items-center mb-5 border-b border-slate-50 pb-4">
                    <div>
                      <h3 className="text-base font-black text-slate-800">{formatDate(selectedDay)}</h3>
                      <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
                        Saldo real neste dia: <span className={dayCumulativeBalance >= 0 ? 'text-emerald-500' : 'text-rose-500'}>{formatCurrency(dayCumulativeBalance)}</span>
                      </div>
                    </div>
                    <div className="text-right">
                       <p className={`text-sm font-bold ${dayBalance >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
